files.content:
.root {
  --vt-surface: #f7f5f2;
  --vt-surface-2: #ffffff;
  --vt-surface-deep: #0f2e2e;
  --vt-ink: #1a1a1a;
  --vt-ink-soft: #5c5c5c;
  --vt-accent: #c4a88c;
  --vt-on-accent: #1a1a1a;
  --vt-accent-ink: #8f7352;
  --vt-on-deep: #f7f5f2;
  --vt-accent-on-deep: #d4bc9c;
  --vt-line: #e6e1da;

  font-family: Manrope, sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.root :where(a, button) {
  color: inherit;
  text-decoration: none;
}

.root :where(h1, h2, h3, h4, h5, h6, p) {
  margin: 0;
}

.root :where(img) {
  display: block;
  max-width: 100%;
  height: auto;
}

.root :focus-visible {
  outline: 2px solid var(--vt-accent-ink);
  outline-offset: 3px;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: color-mix(in srgb, var(--vt-surface) 92%, transparent);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--vt-line);
}

.navIn {
  max-width: 1280px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.logo {
  display: flex;
  align-items: center;
}

.brand {
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.menu {
  display: none;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.navLinks a {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--vt-ink-soft);
}

.navLinks a:hover,
.navLinks a:focus-visible {
  color: var(--vt-ink);
}

.navPhone {
  font-size: 0.9375rem;
  font-weight: 700;
  padding: 0.625rem 1.25rem;
  border-radius: 999px;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
}

.navPhone:hover,
.navPhone:focus-visible {
  background: var(--vt-ink);
}

.hero {
  position: relative;
  overflow: hidden;
  background: var(--vt-surface-2);
}

.heroGrid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: calc(100vh - 65px);
  min-height: calc(100svh - 65px);
}

.heroText {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 4rem 3rem;
  gap: 1.5rem;
}

.kicker {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--vt-accent-ink);
}

.heroTitle {
  font-family: 'EB Garamond', serif;
  font-size: clamp(3rem, 6vw, 5.5rem);
  line-height: 0.95;
  font-weight: 500;
  letter-spacing: -0.03em;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.heroWord {
  color: var(--vt-surface-deep);
}

.heroLine {
  color: var(--vt-ink);
}

.heroMeta {
  font-size: 1.125rem;
  color: var(--vt-ink-soft);
  font-weight: 500;
}

.heroIntro {
  font-size: clamp(1rem, 1.5vw, 1.25rem);
  color: var(--vt-ink-soft);
  max-width: 42ch;
  line-height: 1.7;
}

.heroActions {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  margin-top: 0.5rem;
}

.heroButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0.875rem 1.75rem;
  border-radius: 999px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  font-weight: 700;
  font-size: 0.9375rem;
}

.heroButton:hover,
.heroButton:focus-visible {
  background: var(--vt-accent-ink);
  color: var(--vt-surface-2);
  transform: translateY(-2px);
}

.heroLink {
  font-weight: 700;
  font-size: 0.9375rem;
  color: var(--vt-surface-deep);
  border-bottom: 2px solid var(--vt-accent);
  padding-bottom: 0.25rem;
}

.heroLink:hover,
.heroLink:focus-visible {
  color: var(--vt-ink);
}

.heroMedia {
  position: relative;
  min-height: 100%;
}

.heroImage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.heroBadge {
  position: absolute;
  bottom: 2rem;
  left: 2rem;
  display: flex;
  flex-direction: column;
  padding: 1.5rem;
  background: var(--vt-surface-2);
  border-radius: 1rem;
  box-shadow: 0 20px 60px color-mix(in srgb, var(--vt-surface-deep) 15%, transparent);
}

.heroInitial {
  font-family: 'EB Garamond', serif;
  font-size: 3rem;
  line-height: 1;
  color: var(--vt-surface-deep);
}

.heroTrade {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--vt-ink-soft);
}

.sectionIn {
  max-width: 1280px;
  margin: 0 auto;
  padding: 6rem 1.5rem;
}

.sectionHead {
  max-width: 680px;
  margin-bottom: 3.5rem;
}

.sectionKicker {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--vt-accent-ink);
  margin-bottom: 1rem;
}

.sectionTitle {
  font-family: 'EB Garamond', serif;
  font-size: clamp(2rem, 4vw, 3.25rem);
  line-height: 1.1;
  font-weight: 500;
  letter-spacing: -0.02em;
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.sectionLead {
  font-size: 1.125rem;
  color: var(--vt-ink-soft);
  line-height: 1.7;
}

.services {
  background: var(--vt-surface);
}

.serviceGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
}

.serviceCard {
  position: relative;
  padding: 2.5rem;
  background: var(--vt-surface-2);
  border: 1px solid var(--vt-line);
  border-radius: 1.25rem;
}

.serviceCard:hover {
  transform: translateY(-4px);
  box-shadow: 0 24px 60px color-mix(in srgb, var(--vt-surface-deep) 8%, transparent);
}

.serviceNum {
  position: absolute;
  top: 1.75rem;
  right: 2rem;
  font-family: 'EB Garamond', serif;
  font-size: 2.5rem;
  line-height: 1;
  color: var(--vt-accent);
  opacity: 0.5;
}

.serviceTitle {
  font-family: 'EB Garamond', serif;
  font-size: 1.625rem;
  font-weight: 500;
  margin-bottom: 0.875rem;
  padding-right: 3rem;
}

.serviceDesc {
  color: var(--vt-ink-soft);
  line-height: 1.7;
}

.story {
  background: var(--vt-surface-2);
}

.storyGrid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
}

.storyMedia {
  position: relative;
  min-height: 100%;
}

.storyImage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  min-height: 600px;
  object-fit: cover;
}

.storyText {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 5rem 4rem;
  gap: 1.5rem;
}

.storyKicker {
  font-family: 'EB Garamond', serif;
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--vt-surface-deep);
  margin-bottom: 0.5rem;
}

.storyP {
  font-size: 1.0625rem;
  color: var(--vt-ink-soft);
  line-height: 1.8;
}

.gallery {
  background: var(--vt-surface);
}

.slider {
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 1.5rem;
}

.sliderTrack {
  display: flex;
  gap: 1.25rem;
}

.slide {
  flex: 0 0 70%;
  scroll-snap-align: start;
  border-radius: 1rem;
  overflow: hidden;
  background: var(--vt-surface-2);
}

.slideImage {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}

.slideCaption {
  padding: 1.25rem 1.5rem;
}

.slideCaption strong {
  display: block;
  font-family: 'EB Garamond', serif;
  font-size: 1.25rem;
  font-weight: 500;
  margin-bottom: 0.25rem;
  color: var(--vt-ink);
}

.slideCaption span {
  font-size: 0.875rem;
  color: var(--vt-ink-soft);
}

.contact {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
}

.contactGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

.contactText {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.contactKicker {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--vt-accent-on-deep);
}

.contactTitle {
  font-family: 'EB Garamond', serif;
  font-size: clamp(2rem, 4vw, 3.25rem);
  line-height: 1.1;
  font-weight: 500;
  letter-spacing: -0.02em;
}

.contactLead {
  font-size: 1.125rem;
  color: color-mix(in srgb, var(--vt-on-deep) 80%, transparent);
  max-width: 42ch;
}

.contactButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0.875rem 1.75rem;
  border-radius: 999px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  font-weight: 700;
  font-size: 0.9375rem;
  align-self: flex-start;
}

.contactButton:hover,
.contactButton:focus-visible {
  background: var(--vt-accent-on-deep);
  color: var(--vt-surface-deep);
  transform: translateY(-2px);
}

.contactMeta {
  display: grid;
  gap: 1.25rem;
  margin-top: 1rem;
}

.contactMeta p {
  color: color-mix(in srgb, var(--vt-on-deep) 85%, transparent);
  line-height: 1.7;
}

.contactMeta strong {
  color: var(--vt-on-deep);
  font-weight: 700;
}

.contactFindUs {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.contactSocial {
  display: flex;
  gap: 1rem;
}

.footer {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
  padding: 2rem 0;
}

.footerLegal {
  text-align: center;
  font-size: 0.875rem;
  color: color-mix(in srgb, var(--vt-on-deep) 70%, transparent);
}

@media (prefers-reduced-motion: no-preference) {
  .serviceCard,
  .storyText,
  .slide {
    animation: reveal-up linear both;
    animation-timeline: view();
    animation-range: entry 10% cover 30%;
  }
}

@keyframes reveal-up {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
  .navIn {
    padding: 0.875rem 1.25rem;
  }

  .navLinks,
  .navPhone {
    display: none;
  }

  .menu {
    display: block;
    position: relative;
  }

  .menuBtn {
    list-style: none;
    width: 44px;
    height: 44px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 6px;
    cursor: pointer;
    background: transparent;
    border: none;
  }

  .menuBtn::-webkit-details-marker {
    display: none;
  }

  .menuBtn span {
    display: block;
    width: 24px;
    height: 2px;
    background: var(--vt-ink);
    border-radius: 2px;
  }

  .menu[open] .menuBtn span:first-child {
    transform: translateY(4px) rotate(45deg);
  }

  .menu[open] .menuBtn span:last-child {
    transform: translateY(-4px) rotate(-45deg);
  }

  .menuPanel {
    position: absolute;
    top: calc(100% + 0.75rem);
    right: 0;
    width: 260px;
    background: var(--vt-surface-2);
    border: 1px solid var(--vt-line);
    border-radius: 1rem;
    padding: 1rem;
    box-shadow: 0 20px 60px color-mix(in srgb, var(--vt-surface-deep) 12%, transparent);
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
  }

  .menuPanel a {
    padding: 0.875rem 1rem;
    border-radius: 0.625rem;
    font-weight: 600;
    color: var(--vt-ink-soft);
  }

  .menuPanel a:hover,
  .menuPanel a:focus-visible {
    background: var(--vt-surface);
    color: var(--vt-ink);
  }

  .menuPhone {
    margin-top: 0.5rem;
    background: var(--vt-surface-deep);
    color: var(--vt-on-deep);
    text-align: center;
  }

  .heroGrid {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .heroText {
    padding: 3rem 1.5rem;
    order: 2;
  }

  .heroMedia {
    order: 1;
    min-height: 420px;
  }

  .heroBadge {
    bottom: 1rem;
    left: 1rem;
  }

  .sectionIn {
    padding: 4rem 1.25rem;
  }

  .serviceGrid {
    grid-template-columns: 1fr;
  }

  .storyGrid {
    grid-template-columns: 1fr;
  }

  .storyImage {
    position: relative;
    min-height: 360px;
  }

  .storyText {
    padding: 3rem 1.5rem;
  }

  .slide {
    flex: 0 0 85%;
  }

  .contactGrid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }
}

@media (max-width: 390px) {
  .heroTitle {
    font-size: 2.75rem;
  }

  .heroActions {
    flex-direction: column;
    align-items: stretch;
    gap: 1rem;
  }

  .heroButton,
  .heroLink,
  .contactButton {
    width: 100%;
    text-align: center;
  }

  .heroMedia {
    min-height: 340px;
  }

  .heroBadge {
    padding: 1rem;
  }

  .heroInitial {
    font-size: 2rem;
  }

  .serviceCard {
    padding: 1.75rem;
  }

  .serviceNum {
    top: 1.25rem;
    right: 1.5rem;
    font-size: 2rem;
  }

  .sectionIn {
    padding: 3rem 1rem;
  }

  .slide {
    flex: 0 0 90%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .root {
    scroll-behavior: auto;
  }

  .root :where(.heroButton, .heroLink, .contactButton, .navPhone, .navLinks a, .menuPanel a, .serviceCard, .slide) {
    transition: none;
    transform: none;
  }
}
